260	    /// Where a member went, for the tables.
261	    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
262	    enum Placed {
263	        Row,
264	        Used,
265	        Collapsed,
266	        Unknown,
267	    }
268	
269	    fn inherited(name: &str) -> Member {
270	        Member { name: name.to_owned(), ..Member::default() }
271	    }
272	
273	    fn ambient(name: &str) -> Member {
274	        Member { ambient: true, ..inherited(name) }
275	    }
276	
277	    fn strings(names: &[&str]) -> Vec<String> {
278	        names.iter().map(|name| (*name).to_owned()).collect()
279	    }
280	
281	    fn reading(names: &[&str]) -> Body {
282	        Body { reads: strings(names), ..Body::default() }
283	    }
284	
285	    fn named(name: &str) -> Attribute {
286	        Attribute::Named(name.to_owned())
287	    }
288	
289	    fn element(target: Target, attributes: Vec<Attribute>) -> Element {
290	        Element { target, attributes }
291	    }
292	
293	    /// The evidence of one case, owned: [`Evidence`] borrows it.
294	    #[derive(Default)]
295	    struct Owned {
296	        members: Vec<Member>,
297	        body: Option<Body>,
298	        call_sites: CallSites,
299	    }
300	
301	    impl Owned {
302	        fn decide(&self) -> Shown {
303	            decide(&Evidence { members: &self.members, body: self.body.as_ref(), call_sites: &self.call_sites })
304	        }
305	    }
306	
307	    fn with(members: Vec<Member>, body: Option<Body>) -> Owned {
308	        Owned { members, body, ..Owned::default() }
309	    }
310	
311	    fn placed(shown: &Shown, name: &str) -> Option<Placed> {
312	        let lists = [
313	            (&shown.rows, Placed::Row),
314	            (&shown.used, Placed::Used),
315	            (&shown.collapsed, Placed::Collapsed),
316	            (&shown.unknown, Placed::Unknown),
317	        ];
318	        lists.into_iter().find(|(list, _)| list.iter().any(|n| n == name)).map(|(_, placed)| placed)
319	    }
320	
321	    /// One case of a table: its label, its evidence, and where each named member must go.
322	    type Case<'a> = (&'a str, Owned, &'a [(&'a str, Placed)]);
323	
324	    /// Runs each case and checks where every named member went.
325	    fn table(cases: Vec<Case<'_>>) {
326	        for (case, evidence, expected) in cases {
327	            let shown = evidence.decide();
328	            for (name, want) in expected {
329	                assert_eq!(placed(&shown, name), Some(*want), "{case}: {name}");
330	            }
331	        }
332	    }
