335	    fn an_inherited_member_the_body_never_reads_stays_in_its_layer() {
336	        let evidence = with(vec![inherited("tone"), inherited("size")], Some(reading(&["size"])));
337	        let shown = evidence.decide();
338	        assert_eq!(shown.collapsed, ["tone"]);
339	        assert_eq!(shown.rows, ["size"]);
340	    }
