512	    #[test]
513	    fn names_carry_no_meaning_and_order_follows_the_members() {
514	        let evidence = |names: [&str; 4]| {
515	            with(
516	                vec![inherited(names[0]), ambient(names[1]), inherited(names[2]), ambient(names[3])],
517	                Some(reading(&[names[2], names[3]])),
518	            )
519	        };
520	        let plain = evidence(["a", "b", "c", "d"]).decide();
521	        let familiar = evidence(["className", "style", "onClick", "children"]).decide();
522	        assert_eq!((plain.rows, plain.used, plain.collapsed), (strings(&["c"]), strings(&["d"]), strings(&["a", "b"])));
523	        assert_eq!(familiar.rows, ["onClick"]);
524	        assert_eq!(familiar.used, ["children"]);
525	        assert_eq!(familiar.collapsed, ["className", "style"]);
526	        assert_eq!(Owned::default().decide(), Shown::default());
527	        let twice = with(vec![inherited("a"), ambient("a")], Some(reading(&["a"]))).decide();
528	        assert_eq!((twice.rows, twice.used), (strings(&["a"]), Vec::new()));
529	    }
