"""Print rows (props + notableInherited) and layers of named components in a canonical `extract --json` output.

usage: python3 rows.py OUT.json Name [Name...]
"""
import json
import sys

d = json.load(open(sys.argv[1]))
P, S, N = d.get("props", {}), d.get("propSets", {}), d.get("nameLists", {})


def ids(value):
    """Prop ids of a props field: a list of ids or prop-set ids, or a map name -> id."""
    out = []
    if isinstance(value, dict):
        value = list(value.values())
    if isinstance(value, str):
        value = [value]
    for i in value or []:
        if i in S:
            out.extend(ids(S[i]))
        else:
            out.append(i)
    return out


def names(value):
    if isinstance(value, str):
        return N.get(value, [])
    return value or []


for v in d["components"].values():
    n = v.get("displayName")
    if n not in sys.argv[2:]:
        continue
    props = [P[i] for i in ids(v["props"])]
    notable = [P[i] for i in ids(v.get("notableInherited"))]
    print(n, "props", len(props), "notable", len(notable), "rows", len(props) + len(notable), v["filePath"][-40:])
    for layer in v["inheritance"]:
        print("  L", layer["typeName"], layer["fileName"][-40:], layer.get("htmlElement"), layer["totalProps"],
              "members", len(names(layer.get("members"))), "used", names(layer.get("used")))
    parents = {}
    for p in props + notable:
        key = (p.get("parent") or {}).get("name")
        parents[key] = parents.get(key, 0) + 1
    print("  parents", dict(sorted(parents.items(), key=lambda kv: -kv[1])[:12]))
    if len(props) + len(notable) < 40:
        print("  names", sorted(p["name"] for p in props), sorted(p["name"] for p in notable))

